            _ => self.show_failure(),
        }
    }

    fn show(&mut self, items: &[BehaviorValue]) {
        self.products = items.iter().filter_map(Self::name).collect();
        self.error = String::new();
    }

    fn name(item: &BehaviorValue) -> Option<String> {
        match item {
