@Helper
class CatalogAdapterHelper:
    ROWS: list[dict[str, object]] = [{'id': 1, 'status': 'active'}, {'id': 2, 'status': 'retired'}]

    @staticmethod
    async def execute(command: dict[str, object], execution: object) -> object:
        query = command['query']
        condition = query['where'][0]
        keep_unequal_rows = condition['operator'] == 'ne'
        matching_rows = []
        for row in CatalogAdapterHelper.ROWS:
            is_equal = row[condition['field']] == condition['value']
            is_match = is_equal
            if keep_unequal_rows:
                is_match = not is_equal
            if is_match:
                matching_rows.append(row)
        if query['kind'] == 'count':
            return len(matching_rows)
        return matching_rows[:query['page']['size']]

[Helper]
public sealed class CatalogAdapterHelper : BehaviorEntityAdapter {
    static readonly BehaviorJSON Rows = BehaviorJSON.Parse("[{\"id\":1,\"status\":\"active\"},{\"id\":2,\"status\":\"retired\"}]");

    public System.Threading.Tasks.Task<BehaviorJSON> execute(BehaviorJSON command, BehaviorExecution execution) {
        var query = command.Get("query");
        var condition = query.Get("where").Items[0];
        bool keepUnequalRows = condition.Get("operator").Text == "ne";
        var matchingRows = new System.Collections.Generic.List<BehaviorJSON>();
        foreach (var row in Rows.Items) {
            bool isEqual = row.Get(condition.Get("field").Text).ToString() == condition.Get("value").ToString();
            bool isMatch = keepUnequalRows ? !isEqual : isEqual;
            if (isMatch) matchingRows.Add(row);
        }
        if (query.Get("kind").Text == "count") {
            return System.Threading.Tasks.Task.FromResult(BehaviorJSON.From(matchingRows.Count));
        }
        return System.Threading.Tasks.Task.FromResult(BehaviorJSON.Array(matchingRows.ToArray()));
    }
}

#[Helper]
struct CatalogAdapterHelper;
impl BehaviorEntityAdapter for CatalogAdapterHelper {
    fn execute(&self, command: &BehaviorEntityCommand, execution: &BehaviorExecution) -> BehaviorResult<BehaviorValue> {
        execution.check()?;
        let rows = [("active", 1.0), ("retired", 2.0)];
        let query = command.query.as_ref().ok_or_else(behavior_invalid)?;
        let Some(BehaviorValue::Array(conditions)) = query.get("where") else {
            return Err(behavior_invalid());
        };
        let condition = conditions.first().ok_or_else(behavior_invalid)?;
        let keep_unequal_rows = condition.get("operator") == Some(&BehaviorValue::String("ne".into()));
        let wanted_status = condition.get("value").cloned().unwrap_or(BehaviorValue::Null);
        let mut matching_rows = Vec::new();
        for (status, id) in rows {
            let is_equal = BehaviorValue::from(status) == wanted_status;
            let is_match = if keep_unequal_rows { !is_equal } else { is_equal };
            if !is_match {
                continue;
            }
            let row = BehaviorValue::object([("id", BehaviorValue::Number(id)), ("status", BehaviorValue::from(status))]);
            matching_rows.push(row);
        }
        match query.get("kind") {
            Some(BehaviorValue::String(kind)) if kind == "count" => Ok(BehaviorValue::Number(matching_rows.len() as f64)),
            _ => Ok(BehaviorValue::Array(matching_rows)),
        }
    }
}

impl CatalogAdapterHelper {
    fn new() -> Self { Self }
}

