@Helper
class LedgerAdapterHelper:
    TRANSACTION = 'transaction'
    ACTION = 'action'
    commands: list[str] = []
    rows: list[dict[str, object]] = [{'id': 1, 'status': 'open'}, {'id': 2, 'status': 'settled'}]
    sequence = 0

    @staticmethod
    async def execute(command: dict[str, object], execution: object) -> object:
        if command['operation'] == LedgerAdapterHelper.TRANSACTION:
            identifier = command.get(LedgerAdapterHelper.TRANSACTION)
            entry = command[LedgerAdapterHelper.ACTION]
            if identifier:
                entry = command[LedgerAdapterHelper.ACTION] + ':' + identifier
            LedgerAdapterHelper.commands.append(entry)
            if command[LedgerAdapterHelper.ACTION] != 'begin':
                return {'ok': True}
            LedgerAdapterHelper.sequence += 1
            return {LedgerAdapterHelper.TRANSACTION: f't{LedgerAdapterHelper.sequence}'}
        query = command['query']
        transaction = command.get(LedgerAdapterHelper.TRANSACTION, 'none')
        LedgerAdapterHelper.commands.append(f"{query['kind']}@{transaction}")
        status = query['where'][0]['value']
        matching_rows = [row for row in LedgerAdapterHelper.rows if row['status'] == status]
        if query['kind'] == 'count':
            return len(matching_rows)
        return matching_rows

@Helper
class LedgerAdapterHelper implements Behaviors.EntityAdapter {
    private static final String TRANSACTION = "transaction";
    private static final String ACTION = "action";
    private static final String KIND = "kind";
    static final java.util.List<String> commands = new java.util.ArrayList<>();
    static int sequence = 0;

    public Object execute(java.util.Map<String, Object> command, Behaviors.Execution execution) {
        Object identifier = command.get(TRANSACTION);
        if (command.get("operation").equals(TRANSACTION)) {
            String entry = String.valueOf(command.get(ACTION));
            if (identifier != null) entry = entry + ":" + identifier;
            commands.add(entry);
            if (!command.get(ACTION).equals("begin")) return java.util.Map.of("ok", true);
            sequence++;
            return java.util.Map.of(TRANSACTION, "t" + sequence);
        }
        java.util.Map<String, Object> query = Behaviors.map(command.get("query"));
        Object transaction = identifier;
        if (transaction == null) transaction = "none";
        commands.add(query.get(KIND) + "@" + transaction);
        if (query.get(KIND).equals("count")) return 1L;
        return java.util.List.of(java.util.Map.of("id", 1L, "status", "open"));
    }
}

