[Helper]
public sealed class LedgerAdapterHelper : BehaviorEntityAdapter {
    private const string Transaction = "transaction";
    public static readonly System.Collections.Generic.List<string> commands = new System.Collections.Generic.List<string>();
    private static int sequence = 0;

    public System.Threading.Tasks.Task<BehaviorJSON> execute(BehaviorJSON command, BehaviorExecution execution) {
        var identifier = command.Has(Transaction) ? command.Get(Transaction).Text : null;
        if (command.Get("operation").Text == Transaction) {
            var action = command.Get("action").Text;
            var entry = action;
            if (identifier != null) entry = action + ":" + identifier;
            commands.Add(entry);
            if (action != "begin") return System.Threading.Tasks.Task.FromResult(BehaviorJSON.Parse("{\"ok\":true}"));
            sequence++;
            var answer = BehaviorJSON.Object(new System.Collections.Generic.Dictionary<string, BehaviorJSON> {
                ["transaction"] = BehaviorJSON.From("t" + sequence),
            });
            return System.Threading.Tasks.Task.FromResult(answer);
        }
        var kind = command.Get("query").Get("kind").Text;
        var transaction = identifier ?? "none";
        commands.Add(kind + "@" + transaction);
        if (kind == "count") return System.Threading.Tasks.Task.FromResult(BehaviorJSON.From(1));
        return System.Threading.Tasks.Task.FromResult(BehaviorJSON.Parse("[{\"id\":1,\"status\":\"open\"}]"));
    }
}

#[derive(Default)]
#[Helper]
struct LedgerAdapterHelper {
    sequence: std::sync::Mutex<u32>,
}
impl LedgerAdapterHelper {
    fn commands() -> &'static std::sync::Mutex<Vec<String>> {
        static COMMANDS: std::sync::Mutex<Vec<String>> = std::sync::Mutex::new(Vec::new());
        &COMMANDS
    }
}
impl BehaviorEntityAdapter for LedgerAdapterHelper {
    fn transaction(&self, command: &BehaviorTransactionCommand, _execution: &BehaviorExecution) -> BehaviorResult<BehaviorValue> {
        let entry = match &command.transaction {
            Some(id) => format!("{}:{id}", command.action),
            None => command.action.to_owned(),
        };
        Self::commands().lock().expect("record the transaction").push(entry);
        let mut sequence = self.sequence.lock().expect("sequence");
        *sequence += 1;
        Ok(BehaviorValue::from(format!("t{sequence}")))
    }

    fn execute(&self, command: &BehaviorEntityCommand, _execution: &BehaviorExecution) -> BehaviorResult<BehaviorValue> {
        let query = command.query.as_ref().ok_or_else(behavior_invalid)?;
        let Some(BehaviorValue::String(kind)) = query.get("kind") else {
            return Err(behavior_invalid());
        };
        let transaction = command.transaction.as_deref().unwrap_or("none");
        Self::commands().lock().expect("record the query").push(format!("{kind}@{transaction}"));
        if kind == "count" {
            return Ok(BehaviorValue::Number(1.0));
        }
        let row = BehaviorValue::object([("id", BehaviorValue::Number(1.0)), ("status", BehaviorValue::from("open"))]);
        Ok(BehaviorValue::Array(vec![row]))
    }
}

